{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C43"],
      "claim": "Sacubitril absolute oral bioavailability was >70% in healthy subjects, providing direct human evidence that a moderately complex amide/acid-containing oral drug can be highly bioavailable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Neotame, a peptide-like molecule with a free carboxylic acid and amide/ester backbone, had 34.4% systemic availability in humans, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Zafirlukast, an aromatic methoxy/amide drug, had approximately 35% oral bioavailability in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Idasanutlin absolute oral bioavailability was 40.1% in patients with solid tumors, supporting high F despite a formulation-dependent lower value.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Elagolix, which shares methoxy, amide, and carboxylic-acid features with the query, has good oral bioavailability in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Tianeptine, a carboxylic-acid-containing drug, had about 99% absolute oral bioavailability in healthy young subjects, demonstrating that such acids can be very well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Idasanutlin absolute F was 0.187 in the fed state for the microprecipitated bulk powder formulation, a sub-20% value; this is formulation- and fed-state-specific and outweighed by the 40.1% patient value.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues with direct human absolute/systemic bioavailability data support F ≥20%, mostly 34–99%; the only sub-20% record is a formulation-specific fed-state value for idasanutlin and is outweighed by its 40.1% absolute F and by the overall consistent high-F evidence. Therefore predict high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule.",
    "The query's formulation and prandial state are unspecified; idasanutlin data show that formulation can lower F below 20%.",
    "Exact structural similarity to the query is not quantified; transfer scores are high but not identity."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

